body.script:
//

(function() {
 function htmlEl(tag,classes){var el=document.createElement(tag);if(classes)el.className=classes;return el;}
 function render(raw,title){
  var wrapper=htmlEl('div');wrapper.innerHTML=raw||'';
  var existing=wrapper.querySelector('article.article');
  var root=document.getElementById('lokhit-native')||document.getElementById('lokhit-article-fallback');
  if(!root)return;
  var parent=htmlEl('div','container');
  var crumbs=wrapper.querySelector('.breadcrumbs');
  if(crumbs)parent.appendChild(crumbs);
  var layout=htmlEl('div','content-layout');
  if(existing){
   var origLayout=existing.closest('.content-layout');
   var aside=origLayout&&origLayout.querySelector('aside');
   layout.appendChild(existing);
   if(aside)layout.appendChild(aside);
  }else{
   var article=htmlEl('article','article');
   var h1=htmlEl('h1');h1.textContent=title||document.title;article.appendChild(h1);
   var body=htmlEl('div','article-body');body.innerHTML=raw||'';article.appendChild(body);
   layout.appendChild(article);
  }
  parent.appendChild(layout);root.replaceChildren(parent);
  var native=document.getElementById('lokhit-blog-content');
  if(native&&native.contains(root)&&root.id==='lokhit-article-fallback'){
    var w=document.getElementById('lokhit-native');if(w)w.style.display='none';
  }
 }
 function isArticlePath(){return /^\/[0-9]{4}\/[0-9]{2}\/[^/]+\.html$/.test(location.pathname);}
 function run(){
  if(!isArticlePath())return;
  var rendered=document.querySelector('#lokhit-native .blogger-post-original');
  if(rendered&&rendered.innerHTML.trim()){render(rendered.innerHTML,document.title);return;}
  fetch('/feeds/posts/default?alt=json&max-results=150').then(function(r){if(!r.ok)throw Error('News feed unavailable');return r.json();}).then(function(data){
    var entries=(data.feed&&data.feed.entry)||[];
    var match=entries.find(function(e){return (e.link||[]).some(function(a){if(a.rel!=='alternate')return false;try{return new URL(a.href).pathname===location.pathname;}catch(err){return false;}});});
    if(!match){return;}
    render(match.content&&match.content.$t||'',match.title&&match.title.$t||'');
  }).catch(function(e){console.error('Lokhit article fallback',e);});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
})();
//

//

/* Shared article presentation – centrally maintained in Blogger theme.
   Applies to imported clean posts and new Blogger posts; never edits post bodies. */
(function(){
 'use strict';
 if(!/^\/\d{4}\/\d{2}\/[^/]+\.html$/.test(location.pathname))return;
 var store=null, loading=false;
 function elt(tag,cls,text){
   var el=document.createElement(tag);
   if(cls)el.className=cls;
   if(text!==undefined)el.textContent=text;
   return el;
 }
 function button(text, kind){
   var b=elt('button','share-btn share-'+kind,text);
   b.type='button';b.setAttribute('data-share',kind);
   b.setAttribute('aria-label',text+' — ही बातमी शेअर करा');
   b.style.cursor='pointer';
   return b;
 }
 function bar(){
   var box=elt('div','share-bar');
   box.appendChild(elt('strong','', 'ही बातमी शेअर करा :'));
   [['WhatsApp','wa'],['Facebook','fb'],['X','x'],['Telegram','tg'],['लिंक कॉपी','copy'],['इतर','native']]
    .forEach(function(pair){box.appendChild(button(pair[0],pair[1]));});
   return box;
 }
 function ownUrl(e){
   var a=(e.link||[]).find(function(x){return x.rel==='alternate' && x.type==='text/html';});
   if(!a)return '';
   try{var url=new URL(a.href);return url.hostname===location.hostname?url.href:'';}catch(err){return '';}
 }
 function photo(e){
   var content=e.content&&e.content.$t||'';
   var box=elt('div');box.innerHTML=content;
   var img=box.querySelector('.article-figure img, img');
   if(img){var src=img.getAttribute('src');if(/^https:\/\//i.test(src||''))return src;}
   var thumbnail=e.media$thumbnail&&e.media$thumbnail.url;
   return /^https:\/\//i.test(thumbnail||'')?thumbnail:'https://catonpe-droid.github.io/lokhit-maharashtra/assets/img/logo.webp';
 }
 function dateOf(e){
   var d=new Date((e.published&&e.published.$t)||'');
   if(isNaN(d.getTime()))return '';
   return d.toLocaleDateString('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'2-digit',year:'numeric'}).replace(/\//g,'-');
 }
 function card(e){
   var url=ownUrl(e);if(!url)return null;
   var a=elt('a','news-card');a.href=url;
   var img=elt('img');img.src=photo(e);img.alt='';img.loading='lazy';
   var bd=elt('div','card-body');
   var label=(e.category||[]).find(function(x){return x.scheme==='http://www.blogger.com/atom/ns#';});
   bd.appendChild(elt('span','category-kicker',label?label.term:'ताज्या बातम्या'));
   bd.appendChild(elt('h3','',e.title&&e.title.$t||''));
   var note=e.summary&&e.summary.$t||'';
   var p=elt('div');p.innerHTML=note;
   bd.appendChild(elt('p','',p.textContent.slice(0,140)));
   bd.appendChild(elt('div','meta',dateOf(e)));
   a.appendChild(img);a.appendChild(bd);return a;
 }
 function decorate(a){
   if(!a || a.getAttribute('data-lokhit-share-v3')==='1')return;
   a.setAttribute('data-lokhit-share-v3','1');
   var body=a.querySelector('.article-body');
   if(!body){
     body=elt('div','article-body');
     while(a.children.length>1)body.appendChild(a.children[1]);
     a.appendChild(body);
   }
   // Clean posts already contain summary/photo; move those to the article position
   // from the original GitHub layout, rather than rendering them as body paragraphs.
   var summary=body.querySelector(':scope > .article-summary');
   if(summary)a.insertBefore(summary,body);
   var figure=body.querySelector(':scope > .article-figure');
   if(figure)a.insertBefore(figure,body);
   var meta=a.querySelector(':scope > .meta');
   if(!meta){
     meta=elt('div','meta');
     meta.appendChild(elt('span','', '✍ लोकहित महाराष्ट्र डिजिटल डेस्क'));
     var d=document.querySelector('meta[property="article:published_time"]');
     if(d&&d.content)meta.appendChild(elt('span','', '📅 '+new Date(d.content).toLocaleDateString('en-GB',{timeZone:'Asia/Kolkata'})));
     a.insertBefore(meta,figure||body);
   }
   // If an imported article already includes buttons, leave them unchanged.
   var bars=Array.from(a.querySelectorAll(':scope > .share-bar'));
   if(bars.length===0){
     a.insertBefore(bar(),body);
     body.insertAdjacentElement('afterend',bar());
   }else if(bars.length===1){
     body.insertAdjacentElement('afterend',bar());
   }
 }
 function fillNews(a,feed){
   if(!feed || a.getAttribute('data-lokhit-related-v3')==='1')return;
   a.setAttribute('data-lokhit-related-v3','1');
   var present=a.querySelector('.related-grid');
   var items=(feed.entry||[]).filter(function(e){return ownUrl(e)&&new URL(ownUrl(e)).pathname!==location.pathname;});
   if(!present){
     var head=elt('div','section-head');head.appendChild(elt('h2','', 'संबंधित बातम्या'));
     var grid=elt('div','related-grid');
     items.slice(0,4).forEach(function(e){var c=card(e);if(c)grid.appendChild(c);});
     if(grid.children.length){a.appendChild(head);a.appendChild(grid);}
   }
   var layout=a.closest('.content-layout');
   if(layout&&!layout.querySelector('aside')){
     var aside=elt('aside');
     var panel=elt('div','side-panel sidebar-box');
     panel.appendChild(elt('div','panel-title', 'ताज्या बातम्या'));
     var content=elt('div','panel-content');
     (feed.entry||[]).filter(function(e){return ownUrl(e);}).slice(0,9).forEach(function(e){
       var link=elt('a','latest-item');link.href=ownUrl(e);
       link.appendChild(elt('span','latest-dot','•'));
       link.appendChild(elt('span','',e.title&&e.title.$t||''));content.appendChild(link);
     });
     panel.appendChild(content);aside.appendChild(panel);layout.appendChild(aside);
   }
 }
 function show(){
   var a=document.querySelector('#lokhit-article-fallback article.article') ||
         document.querySelector('#lokhit-native article.article');
   if(!a)return;
   decorate(a);
   if(store)fillNews(a,store);
 }
 function load(){
   if(loading)return;loading=true;
   fetch('/feeds/posts/default?alt=json&max-results=150',{credentials:'same-origin'})
    .then(function(r){if(!r.ok)throw Error('Blogger feed unavailable');return r.json();})
    .then(function(data){store=data.feed||null;show();})
    .catch(function(e){console.warn('Latest news not loaded:',e);});
 }
 function boot(){
   var root=document.getElementById('lokhit-article-fallback');
   if(root)new MutationObserver(function(){show();}).observe(root,{childList:true});
   show();load();
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
//

//

/* Lokhit share actions are managed by the Blogger theme for EVERY post. */
(function(){
  'use strict';
  function getAction(button) {
    var kind=button.getAttribute('data-share');
    if(kind)return kind;
    var classes=button.classList;
    for(var name of ['wa','fb','x','tg','copy','native']){
      if(classes.contains('share-'+name))return name;
    }
    return '';
  }
  function notify(message){
    var el=document.getElementById('toast');
    if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');document.body.appendChild(el);}
    el.textContent=message;el.classList.add('visible');
    setTimeout(function(){el.classList.remove('visible')},2500);
  }
  function copyLink(url){
    if(navigator.clipboard&&window.isSecureContext){
      navigator.clipboard.writeText(url).then(function(){notify('बातमीची लिंक कॉपी झाली')}).catch(function(){fallback(url)});
    }else fallback(url);
  }
  function fallback(url){
    var input=document.createElement('textarea');
    input.value=url;input.setAttribute('readonly','');
    input.style.cssText='position:fixed;left:-10000px;top:0';
    document.body.appendChild(input);input.select();
    var ok=false;
    try{ok=document.execCommand('copy')}catch(err){}
    input.remove();
    if(ok)notify('बातमीची लिंक कॉपी झाली');
    else window.prompt('ही बातमीची लिंक कॉपी करा:',url);
  }
  document.addEventListener('click',function(event){
    var btn=event.target.closest('button.share-btn');
    if(!btn||!btn.closest('.share-bar'))return;
    var mode=getAction(btn);
    if(!mode)return;
    event.preventDefault();
    event.stopImmediatePropagation(); // avoid duplicate handling by legacy GitHub site.js
    var url=location.href.split('#')[0];
    var h=document.querySelector('#lokhit-article-fallback article.article h1, #lokhit-native article.article h1');
    var title=h?h.textContent.trim():document.title.replace(/\s*[|–—-]\s*लोकहित महाराष्ट्र\s*$/,'').trim();
    if(mode==='copy'){copyLink(url);return;}
    if(mode==='native'){
      if(navigator.share){
        navigator.share({title:title,url:url,text:title}).catch(function(err){if(err&&err.name!=='AbortError')copyLink(url)});
      }else copyLink(url);
      return;
    }
    var shareUrls={
      wa:'https://api.whatsapp.com/send?text='+encodeURIComponent(title+'\n'+url),
      fb:'https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url),
      x:'https://twitter.com/intent/tweet?text='+encodeURIComponent(title)+'&url='+encodeURIComponent(url),
      tg:'https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent(title)
    };
    if(shareUrls[mode])window.open(shareUrls[mode],'_blank','noopener,noreferrer');
  },true);
})();

