//

/* Lokhit Maharashtra: Layout Manager and dynamic homepage, compatible with default markup. */
(function(){
  'use strict';
  var ROOT='https://catonpe-droid.github.io/lokhit-maharashtra/';
  var entries=[], started=false;
  var hub=document.getElementById('lk-layout-manager');
  function byId(id){return document.getElementById(id);}
  function slot(id){return byId(id);}
  function el(tag, cls, title){
    var out=document.createElement(tag);
    if(cls)out.className=cls;
    if(title!==undefined)out.textContent=title;
    return out;
  }
  function links(id){
    var n=slot(id);
    if(!n)return [];
    return Array.from(n.querySelectorAll('.widget-content a[href],.widget li a[href],.widget a[href]')).filter(function(a){
      return !a.closest('.item-control,.quickedit')&&!a.classList.contains('quickedit')&&a.getAttribute('href')&&!a.href.includes('javascript:');
    }).map(function(a){return {label:a.textContent.trim(),url:a.href};}).filter(function(x){return x.label&&x.url;});
  }
  function widgets(id){
    var n=slot(id);if(!n)return [];
    return Array.from(n.children).filter(function(a){return a.classList&&a.classList.contains('widget');});
  }
  function entryLink(e){
    var a=(e.link||[]).find(function(x){return x.rel==='alternate'&&x.type==='text/html';});
    return a?a.href:'';
  }
  function entryTitle(e){return (e.title&&e.title.$t)||'';}
  function entryLabels(e){return (e.category||[]).filter(function(x){return x.scheme==='http://www.blogger.com/atom/ns#';}).map(function(x){return x.term;});}
  function cleanText(html){
    var div=el('div');div.innerHTML=html||'';
    return (div.textContent||'').replace(/\s+/g,' ').trim();
  }
  function image(e){
    var div=el('div');div.innerHTML=(e.content&&e.content.$t)||'';
    var img=div.querySelector('.article-figure img, img');
    var src=img?img.getAttribute('src'):'';
    if(src&&/^https:\/\//i.test(src))return src;
    if(e.media$thumbnail&&e.media$thumbnail.url)return e.media$thumbnail.url;
    return ROOT+'assets/img/logo.webp';
  }
  function desc(e){
    var text=cleanText((e.summary&&e.summary.$t)||(e.content&&e.content.$t)||'');
    return text.slice(0,160);
  }
  function niceDate(e){
    var d=new Date(e.published&&e.published.$t||'');
    if(isNaN(d.getTime()))return '';
    var dateParts=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Kolkata'}).format(d);
    return dateParts.replace(/\//g,'-');
  }
  function findEntry(url){
    try{var u=new URL(url,location.origin).pathname;return entries.find(function(e){return new URL(entryLink(e),location.origin).pathname===u;})||null;}
    catch(err){return null;}
  }
  function makeCard(e){
    var a=el('a','news-card');a.href=entryLink(e);
    var img=el('img');img.src=image(e);img.alt=entryTitle(e);img.loading='lazy';
    var box=el('div','card-body');
    box.appendChild(el('span','category-kicker',entryLabels(e)[0]||'ताज्या बातम्या'));
    box.appendChild(el('h3','',entryTitle(e)));
    box.appendChild(el('p','',desc(e)));
    var meta=el('div','meta');meta.appendChild(el('span','', '📅 '+niceDate(e)));meta.appendChild(el('span','', 'लोकहित डेस्क'));
    box.appendChild(meta);a.appendChild(img);a.appendChild(box);return a;
  }
  function hasContent(id){return widgets(id).length>0;}
  function moveArea(id,parent,before){
    var ws=widgets(id);
    if(!ws.length||!parent)return null;
    var group=el('section','page-section lk-added-section');
    group.setAttribute('data-layout-region',id);
    ws.forEach(function(w){group.appendChild(w);});
    parent.insertBefore(group,before||null);
    return group;
  }
  function addMenu(){
    var items=links('LkMenuSettings');
    var target=byId('nav-links');
    if(items.length===0||!target)return;
    var frag=document.createDocumentFragment();
    items.forEach(function(item){
      var a=el('a','',item.label);a.href=item.url;
      try{if(new URL(item.url).pathname===location.pathname)a.className='active';}catch(e){}
      frag.appendChild(a);
    });
    target.replaceChildren(frag);
  }
  function addBreaking(){
    var items=links('LkTickerSettings');
    var track=document.querySelector('.ticker-move');
    if(!items.length||!track)return;
    var parts=[];
    for(var i=0;i<2;i++){
      var segment=el('div','ticker-segment');
      if(i===1){segment.setAttribute('aria-hidden','true');segment.inert=true;}
      items.forEach(function(item){
        var span=el('span','ticker-item');
        var star=el('span','ticker-star','◆');star.setAttribute('aria-hidden','true');
        var link=el('a','',item.label);link.href=item.url;
        span.appendChild(star);span.appendChild(link);segment.appendChild(span);
      });
      parts.push(segment);
    }
    track.replaceChildren.apply(track,parts);
  }
  function addHeader(){
    var ws=widgets('LkHeaderSettings');if(!ws.length)return;
    var content=ws[0].querySelector('.widget-content')||ws[0],img=content.querySelector('img');
    var logo=document.querySelector('.site-logo');
    if(img&&logo&&img.src)logo.src=img.src;
    var tagline=content.querySelector('[data-lokhit-tagline]');
    if(tagline){var current=document.querySelector('.brand-tagline');if(current)current.textContent=tagline.textContent.trim();}
  }
  function addFooter(){
    var items=links('LkFooterLinks');
    var footer=document.querySelector('.footer-grid');
    if(footer){
      var cols=footer.children, legal=cols[3];
      if(legal&&items.length){
        Array.from(legal.querySelectorAll('a')).forEach(function(a){a.remove();});
        items.forEach(function(item){var a=el('a','',item.label);a.href=item.url;legal.appendChild(a);});
      }
    }
    var extra=widgets('LkFooterContent');
    var footBottom=document.querySelector('.footer-bottom');
    if(footBottom&&extra.length){
      var box=el('div','lk-custom-footer');extra.forEach(function(x){box.appendChild(x);});
      footBottom.parentNode.insertBefore(box,footBottom);
    }
  }
  function addHomeSlots(){
    var hero=document.querySelector('.hero-layout');
    if(!hero)return;
    var container=hero.parentNode,latest=byId('homepage-latest-grid');
    moveArea('LkHomeTop',container,hero);
    moveArea('LkHomeAfterSlider',container,hero.nextSibling);
    if(latest){var sec=latest.closest('section');if(sec)moveArea('LkHomeAfterLatest',container,sec.nextSibling);}
    moveArea('LkHomeBottom',container,null);
    var heroRight=document.querySelector('.hero-stack');
    var ws=widgets('LkHomeSidebar');
    if(ws.length&&heroRight){
      var panel=el('div','lk-home-side-widget');
      ws.forEach(function(w){panel.appendChild(w);});heroRight.appendChild(panel);
    }
  }
  function makeHeroSlide(e,index){
    var a=el('a','hero-main hero-slide'+(index===0?' is-active':''));
    a.href=entryLink(e);a.setAttribute('data-slide-index',String(index));
    a.setAttribute('aria-hidden',index===0?'false':'true');a.tabIndex=index===0?0:-1;
    var img=el('img');img.src=image(e);img.alt=entryTitle(e);if(index===0)img.setAttribute('fetchpriority','high');
    var content=el('div','hero-content');
    content.appendChild(el('span','tag',entryLabels(e)[0]||'ताज्या बातम्या'));
    content.appendChild(el('h1','',entryTitle(e)));
    content.appendChild(el('p','',desc(e)));
    content.appendChild(el('div','meta','📅 '+niceDate(e)+' · लोकहित महाराष्ट्र डिजिटल डेस्क'));
    a.appendChild(img);a.appendChild(content);return a;
  }
  function renderSliders(){
    var items=links('LkSliderSettings');
    var slideRoot=byId('hero-slider');
    if(items.length&&slideRoot){
      var selected=items.map(function(x){return findEntry(x.url);}).filter(Boolean).slice(0,8);
      if(selected.length){
        Array.from(slideRoot.querySelectorAll('.hero-slide')).forEach(function(x){x.remove();});
        var anchor=slideRoot.querySelector('.hero-arrow');
        selected.forEach(function(e,i){slideRoot.insertBefore(makeHeroSlide(e,i),anchor);});
        var dots=slideRoot.querySelector('.hero-dots');
        if(dots){
          dots.replaceChildren();
          selected.forEach(function(e,i){
            var b=el('button','hero-dot'+(i===0?' is-active':''));
            b.type='button';b.setAttribute('data-slide-to',String(i));
            b.setAttribute('aria-label','बातमी स्लाइड '+(i+1));
            b.setAttribute('aria-current',i===0?'true':'false');
            dots.appendChild(b);
          });
        }
        document.dispatchEvent(new Event('lokhit:hero-updated'));
      }
    }
    var right=links('LkFeaturedCards'),stack=document.querySelector('.hero-stack');
    if(right.length&&stack){
      var cards=right.map(function(x){return findEntry(x.url);}).filter(Boolean).slice(0,5);
      if(cards.length){
        stack.replaceChildren();
        cards.forEach(function(e){
          var a=el('a','stack-card');a.href=entryLink(e);
          var img=el('img');img.src=image(e);img.loading='lazy';img.alt='';
          var body=el('div');body.appendChild(el('h3','',entryTitle(e)));
          body.appendChild(el('span','meta',niceDate(e)));
          a.appendChild(img);a.appendChild(body);stack.appendChild(a);
        });
      }
    }
  }
  var fixedTitles=['दुष्काळ विशेष','महाराष्ट्र','शेती','शासन योजना','पशुसंवर्धन','अधिक बातम्या'];
  function sectionTitle(sec){var h=sec.querySelector('.section-head h2');return h?h.textContent.trim():'';}
  function findSection(title){return Array.from(document.querySelectorAll('main .page-section')).find(function(s){return sectionTitle(s)===title;});}

  function sectionTitle(sec){var h=sec.querySelector(':scope > .section-head h2');return h?h.textContent.trim():'';}
  function findSection(title){return Array.from(document.querySelectorAll('main .container > section.page-section')).find(function(s){return sectionTitle(s)===title;});}
  function getHomepageConfig(){
    return links('LkHomepageSettings').map(function(item){
      var text=item.label, split=text.match(/^(.*?)\s*\|\s*(\d+)\s*$/);
      var name=(split?split[1]:text).trim();
      var limit=Math.max(1,Math.min(24,split?parseInt(split[2],10):4));
      var url=new URL(item.url,location.href),category='';
      if(url.pathname.indexOf('/search/label/')===0)category=decodeURIComponent(url.pathname.split('/search/label/')[1]).replace(/\/$/,'');
      return {name:name,limit:limit,url:item.url,category:category};
    });
  }
  function manageSections(){
    var selection=getHomepageConfig();
    if(!selection.length)return;
    var hero=document.querySelector('main .hero-layout');if(!hero)return;
    var container=hero.parentNode;
    var existing=Array.from(container.querySelectorAll(':scope > section.page-section')).filter(function(s){
      return !s.classList.contains('hero-layout')&&!s.classList.contains('lk-added-section');
    });
    existing.forEach(function(s){
      s.setAttribute('data-lk-managed','true');s.hidden=true;
      if(s.classList.contains('drought-banner'))s.setAttribute('data-lk-special','drought');
      if(s.classList.contains('live-tv-section'))s.setAttribute('data-lk-special','live');
    });
    var bottom=container.querySelector('section[data-layout-region="LkHomeBottom"]');
    selection.forEach(function(item){
      var name=item.name, sec=null;
      if(item.url.indexOf('#lk-drought-banner')>=0)sec=existing.find(function(s){return s.getAttribute('data-lk-special')==='drought';});
      else if(item.url.indexOf('#lk-live-tv')>=0)sec=existing.find(function(s){return s.getAttribute('data-lk-special')==='live';});
      else sec=existing.find(function(s){return sectionTitle(s)===name;});
      if(!sec){
        sec=el('section','page-section');sec.setAttribute('data-lk-managed','true');
        var heading=el('div','section-head'),h2=el('h2','',name),a=el('a','', 'सर्व बातम्या ›');
        a.href=item.url;heading.appendChild(h2);heading.appendChild(a);
        sec.appendChild(heading);sec.appendChild(el('div','news-grid'));
        existing.push(sec);
      }
      sec.hidden=false;
      sec.setAttribute('data-lk-limit',String(item.limit));
      sec.setAttribute('data-lk-category',item.category);
      if(item.name==='ताज्या बातम्या'||item.name==='अधिक बातम्या')sec.setAttribute('data-lk-all','true');
      else sec.removeAttribute('data-lk-all');
      container.insertBefore(sec,bottom||null);
    });
    var latest=existing.find(function(s){return sectionTitle(s)==='ताज्या बातम्या'&&!s.hidden;});
    var afterLatest=container.querySelector('section[data-layout-region="LkHomeAfterLatest"]');
    if(latest&&afterLatest)latest.insertAdjacentElement('afterend',afterLatest);
  }
  function updateCards(){
    if(!entries.length)return;
    var sections=Array.from(document.querySelectorAll('main .container > section.page-section'));
    sections.forEach(function(sec){
      var grid=sec.querySelector(':scope > .news-grid');
      var title=sectionTitle(sec);
      if(!grid||!title||sec.hidden)return;
      var category=sec.getAttribute('data-lk-category')||title;
      var all=sec.getAttribute('data-lk-all')==='true'||title==='ताज्या बातम्या'||title==='अधिक बातम्या';
      var list=all?entries:entries.filter(function(e){return entryLabels(e).includes(category);});
      var limit=parseInt(sec.getAttribute('data-lk-limit')||'',10);
      if(!Number.isFinite(limit))limit=title==='ताज्या बातम्या'?12:4;
      grid.replaceChildren();
      list.slice(0,Math.max(1,Math.min(24,limit))).forEach(function(e){grid.appendChild(makeCard(e));});
      if(!grid.children.length){
        var empty=el('p','empty-state','या विभागात सध्या बातम्या उपलब्ध नाहीत.');
        grid.appendChild(empty);
      }
    });
  }
  function homeArticleLinks(){
    if(!entries.length)return;
    var byTitle=new Map(entries.map(function(e){return [entryTitle(e),entryLink(e)];}));
    document.querySelectorAll('a[href*="/lokhit-maharashtra/batmi/"]').forEach(function(a){
      var text=a.textContent.trim(),match=entries.find(function(e){return entryTitle(e)===text||a.querySelector('h1,h2,h3')&&entryTitle(e)===a.querySelector('h1,h2,h3').textContent.trim();});
      if(match)a.href=entryLink(match);
    });
  }
  function insertArticleSidebar(){
    if(!/^\/\d{4}\/\d{2}\/[^/]+\.html$/.test(location.pathname))return;
    var post=document.querySelector('#lokhit-article-fallback article.article')||document.querySelector('#lokhit-native article.article');
    if(!post)return;
    var w=widgets('LkArticleSidebar');
    if(!w.length)return;
    var parent=post.closest('.content-layout');
    if(!parent)return;
    var aside=parent.querySelector('aside');
    if(!aside){aside=el('aside');parent.appendChild(aside);}
    var panel=el('div','lk-article-side-widget');w.forEach(function(n){panel.appendChild(n);});aside.appendChild(panel);
  }
  function loadFeed(){
    if(!document.querySelector('.hero-layout'))return;
    fetch('/feeds/posts/default?alt=json&max-results=150',{credentials:'same-origin'})
      .then(function(r){if(!r.ok)throw Error('Feed unavailable');return r.json();})
      .then(function(d){entries=(d.feed&&d.feed.entry)||[];renderSliders();updateCards();homeArticleLinks();})
      .catch(function(e){console.warn('Lokhit Homepage layout feed issue',e);});
  }
  function start(){
    if(started)return;started=true;
    addHeader();addMenu();addBreaking();addFooter();
    if(document.querySelector('.hero-layout')){
      addHomeSlots();manageSections();loadFeed();
    }
    insertArticleSidebar();
    var fallback=byId('lokhit-article-fallback');
    if(fallback){new MutationObserver(function(){insertArticleSidebar();}).observe(fallback,{childList:true});}
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();

