/* Blogger-only navigation. Original GitHub hosts images/styles, not visitor-facing pages. */
(function(){
'use strict';
var SOURCE='https://catonpe-droid.github.io/lokhit-maharashtra/';
var posts={"pawar_drought_visit":"/2026/11/50.html","employment-and-drought-planning":"/2026/11/.html","women-self-help-groups-drought":"/2026/10/_975.html","tanker-request-village-process":"/2026/10/_271.html","rabi-sowing-water-budget":"/2026/10/_64.html","drip-irrigation-water-saving":"/2026/10/_9.html","village-water-conservation":"/2026/10/_20.html","loan-waiver-vs-restructuring":"/2026/10/_38.html","maharashtra-drought-265-305-talukas":"/2026/10/_36.html","marathwada-water-tankers":"/2026/10/_0.html","livestock-water-fodder-crisis":"/2026/10/_18.html","silage-making-safety":"/2026/10/_83.html","fodder-crop-planning":"/2026/10/_16.html","october-water-conservation-rules":"/2026/10/_01.html","central-team-drought-survey":"/2026/10/_03.html","crop-loss-panchnama-guide":"/2026/10/_05.html","fake-relief-links-warning":"/2026/10/_2.html","vk-number-ekyc-relief":"/2026/10/_68.html","silage-subsidy-cattle-owners":"/2026/10/_5.html","mission-murghas-maharashtra":"/2026/10/_41.html"}, pages={"about":"about-us","contact":"contact-us","advertise":"advertising-partnerships","privacy-policy":"privacy-policy","terms":"terms-and-conditions","disclaimer":"disclaimer","grievance":"grievance-redressal","cookie-policy":"cookie-policy","editorial-policy":"editorial-policy","corrections":"corrections-policy","live-tv":"live-tv","video":"video-news"}, titles={"about":"About Us","contact":"Contact Us","advertise":"Advertising & Partnerships","privacy-policy":"Privacy Policy","terms":"Terms & Conditions","disclaimer":"Disclaimer","grievance":"Grievance Redressal","cookie-policy":"Cookie Policy","editorial-policy":"Editorial Policy","corrections":"Corrections Policy","live-tv":"YouTube Live TV | लोकहित महाराष्ट्र","video":"व्हिडिओ बातम्या"}, labels={"maharashtra":"महाराष्ट्र","marathwada":"मराठवाडा","vidarbha":"विदर्भ","dushkal":"दुष्काळ विशेष","sheti":"शेती","shasan-yojana":"शासन योजना","pashusanvardhan":"पशुसंवर्धन","rajkaran":"राजकारण","vishleshan":"विश्लेषण"},livePages={},news=[];
function aLink(e){return (e.link||[]).find(function(x){return x.rel==='alternate'&&x.type==='text/html';});}
function categoryList(e){return (e.category||[]).filter(function(x){return x.scheme==='http://www.blogger.com/atom/ns#';}).map(function(x){return x.term;});}
function convert(href){
 var u;try{u=new URL(href,location.href);}catch(e){return '';}
 var isOld=u.hostname==='catonpe-droid.github.io'&&u.pathname.startsWith('/lokhit-maharashtra/');
 var isLegacyLocal=u.hostname===location.hostname&&(/^\/(?:batmi|vibhag)\//).test(u.pathname);
 if(!isOld&&!isLegacyLocal)return '';
 var route=isOld?u.pathname.slice('/lokhit-maharashtra/'.length):u.pathname.slice(1);
 var parts=route.replace(/\/+$/,'').split('/'),group=parts[0],name=parts[1];
 if(group==='assets'||group==='content'||group==='admin')return '';
 if(group==='vibhag'&&labels[name])return '/search/label/'+encodeURIComponent(labels[name]);
 if(group==='batmi')return posts[name]||'/search';
 if(group==='tajya-batmya'||group==='shodh')return '/search';
 if(!group)return '/';
 if(Object.prototype.hasOwnProperty.call(pages,group))return livePages[group]||'/p/'+pages[group]+'.html';
 return '/search';
}
function correct(root){
 if(!root)return;
 if(root.matches&&root.matches('a[href]'))fix(root);
 if(root.querySelectorAll)root.querySelectorAll('a[href]').forEach(fix);
}
function fix(a){
 var old=a.getAttribute('href');if(!old)return;
 var next=convert(old);
 if(!next){
   var guess=old.match(/^\/p\/([^/]+)\.html$/);
   if(guess)for(var k in pages)if(pages[k]===guess[1]&&livePages[k])next=livePages[k];
 }
 if(next&&next!==old){a.setAttribute('href',next);a.removeAttribute('target');}
}
function newsCard(e){
 var a=document.createElement('a'),body=document.createElement('div'),img=document.createElement('img');
 a.href=aLink(e).href;a.className='news-card';body.className='card-body';
 var html=document.createElement('div');html.innerHTML=e.content&&e.content.$t||'';
 var photo=html.querySelector('.article-figure img,img');
 img.src=(photo&&photo.getAttribute('src'))||(e.media$thumbnail&&e.media$thumbnail.url)||SOURCE+'assets/img/logo.webp';
 img.alt=e.title&&e.title.$t||'';img.loading='lazy';a.appendChild(img);
 var badge=document.createElement('span');badge.className='category-kicker';badge.textContent=categoryList(e)[0]||'ताज्या बातम्या';body.appendChild(badge);
 var h3=document.createElement('h3');h3.textContent=e.title&&e.title.$t||'';body.appendChild(h3);
 var p=document.createElement('p');p.textContent=(e.summary&&e.summary.$t)||'';body.appendChild(p);
 a.appendChild(body);return a;
}
function renderArchive(){
 var path=location.pathname, m=path.match(/^\/search\/label\/(.+?)\/?$/);
 if(!m&&path!=='/search'&&path!=='/search/')return;
 var label=m?decodeURIComponent(m[1].replace(/\+/g,' ')):null;
 var query=new URLSearchParams(location.search).get('q');
 var filtered=news.filter(function(e){
  if(!aLink(e))return false;
  if(label)return categoryList(e).includes(label);
  if(query)return (e.title&&e.title.$t||'').toLowerCase().includes(query.toLowerCase());
  return true;
 });
 var main=document.getElementById('lokhit-blog-content');
 if(!main)return;
 var exists=main.querySelectorAll('.news-grid .news-card');
 if(exists.length&&exists.length===filtered.length)return;
 var old=document.getElementById('lokhit-native-archive');
 if(old)old.remove();
 var container=document.createElement('div');container.id='lokhit-native-archive';container.className='container page-section';
 var section=document.createElement('div');section.className='section-head';
 var h2=document.createElement('h2');h2.textContent=label||'ताज्या बातम्या';section.appendChild(h2);
 container.appendChild(section);
 var grid=document.createElement('div');grid.className='news-grid';
 filtered.forEach(function(e){grid.appendChild(newsCard(e));});
 if(grid.children.length)container.appendChild(grid);
 else {var p=document.createElement('p');p.className='empty-state';p.textContent='या विभागात सध्या बातम्या उपलब्ध नाहीत.';container.appendChild(p);}
 main.appendChild(container);
}
function load(){
 fetch('/feeds/posts/default?alt=json&max-results=150',{credentials:'same-origin'})
 .then(function(r){return r.json()}).then(function(d){news=(d.feed&&d.feed.entry)||[];renderArchive();})
 .catch(function(e){console.warn('Lokhit posts feed',e);});
 fetch('/feeds/pages/default?alt=json&max-results=100',{credentials:'same-origin'})
 .then(function(r){return r.json()}).then(function(d){
  (d.feed&&d.feed.entry||[]).forEach(function(e){
   var link=aLink(e);if(!link)return;
   for(var slug in titles)if(e.title&&e.title.$t===titles[slug])livePages[slug]=new URL(link.href).pathname;
  });
  correct(document);
 }).catch(function(e){console.warn('Lokhit pages feed',e);});
}
function boot(){
 correct(document);
 var queued=false;
 new MutationObserver(function(){if(queued)return;queued=true;setTimeout(function(){queued=false;correct(document);},0);}).observe(document.body,{childList:true,subtree:true});
 document.addEventListener('click',function(e){
  var a=e.target.closest('a[href]');if(a)fix(a);
 },true);
 load();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
