/* Lokhit final: native-domain links + all Blogger images + article formatting. */
(function(){
 'use strict';
 var SRC='https://catonpe-droid.github.io/lokhit-maharashtra/';
 function fullImage(url, size){
   if(!url||!/(?:blogger\.googleusercontent\.com|blogger_img_proxy|bp\.blogspot\.com)/i.test(url))return url;
   return url.replace(/\/(?:w\d+(?:-h\d+)?(?:-c)?|s\d+(?:-[^/]*)?)\//i,'/s'+size+'/');
 }
 function normalizeLink(a){
   if(!a||!a.href)return;
   var u;try{u=new URL(a.href);}catch(e){return;}
   var current=location.hostname;
   if(u.hostname==='lokhitmaharashtraserver.blogspot.com'&&current!=='lokhitmaharashtraserver.blogspot.com'){
     a.href=u.pathname+u.search+u.hash;
   }
 }
 function normalizeAll(){
   document.querySelectorAll('a[href]').forEach(normalizeLink);
 }
 function heroImage(img){
   if(!img||img.dataset.lkPhotoFixed==='1')return;
   var src=img.getAttribute('src')||'';
   if(!src)return;
   img.dataset.lkPhotoFixed='1';
   if(!img.getAttribute('alt')){
     var title=document.querySelector('article.article h1');
     if(title)img.alt=title.textContent.trim();
   }
   var width=img.closest('.lk-feature-image')?1600:1000;
   var upgraded=fullImage(src,width);
   if(upgraded!==src){img.removeAttribute('srcset');img.src=upgraded;}
 }
 function formatArticle(){
   var post=document.querySelector('#lokhit-article-fallback article.article')||document.querySelector('#lokhit-native article.article');
   if(!post)return;
   var body=post.querySelector('.article-body')||post.querySelector('.entry-content');
   if(!body)return;
   if(post.getAttribute('data-lk-images-v7')!=='1'){
     post.setAttribute('data-lk-images-v7','1');
     var featured=post.querySelector('.article-figure');
     if(!featured){
       var first=body.querySelector('img');
       if(first){
         var link=first.closest('a');
         var parent=link&&body.contains(link)?link:first;
         var oldParent=parent.parentElement;
         var figure=document.createElement('figure');
         figure.className='article-figure lk-feature-image';
         figure.appendChild(parent);
         body.parentElement.insertBefore(figure,body);
         if(oldParent&&oldParent!==body&&(!oldParent.textContent||!oldParent.textContent.trim())&&oldParent.children.length===0)oldParent.remove();
         featured=figure;
       }
     }
     if(featured){
       featured.classList.add('lk-feature-image');
       var photo=featured.querySelector('img');
       if(photo){photo.removeAttribute('width');photo.removeAttribute('height');photo.style.removeProperty('width');photo.style.removeProperty('height');photo.loading='eager';photo.setAttribute('fetchpriority','high');}
     }
     var paragraphs=body.querySelectorAll('p');
     paragraphs.forEach(function(p){if(p.style.width)p.style.removeProperty('width');});
   }
   post.querySelectorAll('.article-figure img,.article-body img,.entry-content img').forEach(heroImage);
 }
 function imagesInLists(){
   document.querySelectorAll('main .news-card img, main .hero-slide img, main .stack-card img').forEach(heroImage);
 }
 function boot(){
   normalizeAll();formatArticle();imagesInLists();
   var updating=false;
   new MutationObserver(function(){
     if(updating)return;updating=true;
     setTimeout(function(){updating=false;normalizeAll();formatArticle();imagesInLists();},25);
   }).observe(document.body,{childList:true,subtree:true});
   document.addEventListener('click',function(e){
     var a=e.target.closest('a[href]');if(a)normalizeLink(a);
   },true);
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();

